INSERT INTO `tmp_548_creature_text` (`entry`,`groupid`,`id`,`text`,`type`,`language`,`probability`,`emote`,`duration`,`sound`,`comment`) VALUES
(14688,0,0,'Hardly a fitting introduction, Spear-Wife.  Now, who is this outsider that I\'ve been hearing so much about?',14,0,0,0,0,0,'Prince Sandoval say 1'),
(14688,1,0,'I will make this as easy as possible for you.  Simply come here and die.  That is all that I ask for your many trespasses.  For your sullying of this exalted place of battle.',14,0,0,0,0,0,'Prince Sandoval say 2'),
(14688,2,0,'FOR YOUR EFFRONTERY TO THE LICH KING!',14,0,0,0,0,0,'Prince Sandoval say 3'),
(16128,0,0,'We received Brann\'s message, and we have begun preparations.',12,0,100,1,0,15649,'Rhonin'),
(16128,1,0,'Citizens of Dalaran! Raise your eyes to the skies and observe!',14,0,100,0,0,15650,'Rhonin'),
(16128,2,0,'Today our world\'s destruction has been averted in defiance of our very makers!',14,0,100,0,0,15651,'Rhonin'),
(16128,3,0,'Algalon the Observer, herald of the titans, has been defeated by our brave comrades in the depths of the titan city of Ulduar.',14,0,100,0,0,15652,'Rhonin'),
(16128,4,0,'Algalon was sent here to judge the fate of our world.',14,0,100,0,0,15653,'Rhonin'),
(16128,5,0,'He found a planet whose races had deviated from the titans\' blueprints. A planet where not everything had gone according to plan.',14,0,100,0,0,15654,'Rhonin'),
(16128,6,0,'Cold logic deemed our world not worth saving. Cold logic, however, does not account for the power of free will. It\'s up to each of us to prove this is a world worth saving.',14,0,100,0,0,15655,'Rhonin'),
(16128,7,0,'That our lives... our lives are worth living.',14,0,100,0,0,15656,'Rhonin'),
(23557,0,0,'Get on ya knees and bow.... to da fang and claw!',14,0,100,0,0,12020,'Halazzi - Aggro'),
(23557,1,0,'You gonna leave in pieces!',14,0,100,0,0,0,'Halazzi - Saber'),
(23557,1,1,'Me gonna carve ya now!',14,0,100,0,0,0,'Halazzi - Saber'),
(23557,2,0,'Me gonna carve ya now!',14,0,100,0,0,12021,'Halazzi - Split'),
(23557,3,0,'Spirit, come back to me!',14,0,100,0,0,12022,'Halazzi - Merge'),
(23557,4,0,'You can\'t fight da power!',14,0,100,0,0,12026,'Halazzi - Killed unit'),
(23557,4,1,'Ya all gonna fail!',14,0,100,0,0,12027,'Halazzi - Killed unit'),
(23557,5,0,'Chaga... choka\'jinn.',14,0,100,0,0,12028,'Halazzi - Death'),
(23557,6,0,'Whatch you be doing? Pissin\' yourselves...',14,0,100,0,0,12025,'Halazzi - Death'),
