(23672,0,0,'Halt! Identify yourself immediately!',12,9,100,0,0,0,'Iron Rune Worker'),
(23672,0,1,'This section is off-limits!',12,9,100,0,0,0,'Iron Rune Worker'),
(23672,0,2,'I\'ve never seen one of you around here.',12,9,100,0,0,0,'Iron Rune Worker'),
(23672,0,3,'Hold it! Stop!',12,9,100,0,0,0,'Iron Rune Worker'),
(23672,0,4,'Stop!! Stop!!! Scrap metal moves itself now?',12,9,100,0,0,0,'Iron Rune Worker'),
(23672,1,0,'Right... my bad. Now where was I?',12,9,100,0,0,0,'Iron Rune Worker'),
(23672,1,1,'All hail the great creator!',12,9,100,0,0,0,'Iron Rune Worker'),
(23672,1,2,'You\'re right, of course. Carry on.',12,9,100,0,0,0,'Iron Rune Worker'),
