(27202,0,6,'Wretch!',12,0,100,0,0,0,'Onslaught Raven Priest'),
(27202,1,0,'I sense the taint of this land in you, footman.  Report to the Bishop before the start of your next shift.',12,0,100,1,0,0,'Onslaught Raven Priest'),
(27202,1,1,'Your protection is strong, child.  Continue your work.',12,0,100,1,0,0,'Onslaught Raven Priest'),
(27202,1,2,'The Grand Admiral himself has come to see to our dedication.  If I see you slacking on your post again, I will gut you myself.',12,0,100,5,0,0,'Onslaught Raven Priest'),
