(33285,1,0,'Victory is mine!',12,7,100,0,0,0,'Argent Valiant'),
(33285,1,1,'It seems you still need more practice. Perhaps another time.',12,7,100,0,0,0,'Argent Valiant'),
(33285,1,2,'I have won. Better luck another time, friend.',12,7,100,0,0,0,'Argent Valiant'),
(33285,1,3,'I am afraid you will need more practice to defeat me.',12,7,100,0,0,0,'Argent Valiant'),
